"""
Named errors for the state machines' Retry rules.

The AWS part (AWSTransientError, is_transient, is_transient_status, transient_aws_errors) is the shared
aws_errors module, distributed by Installer/refresh and packaged in AwsErrorsLayer; it is re-exported here
so that SOAR's Lambdas import everything from one place. The ticketing errors are SOAR's own.
"""

from aws_errors import (AWSTransientError, THROTTLING_CODES, TIMEOUT_CODES,  # noqa: F401
                        is_transient, is_transient_status, transient_aws_errors)


class TicketingTransientError(Exception):
    """The ticketing system was rate limited, failed on its side or could not be reached. The state machine
    retries it."""


class TicketingRequestError(Exception):
    """The ticketing system refused the request for a reason a retry will not change. Not retried."""
